content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-19-photo-album-016

=== 用户原始指令 (query.txt) ===
想要个运动精彩瞬间的横向卡片,左边放个运动图标,右边横着排跑步/骑行/游泳三组,每组上面"本周已攒 N 张",提醒我赶紧凑满本月运动合集(还差 7 张),点能跳运动健康 app,有点紧迫感的渐变。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "想要个运动精彩瞬间的横向卡片,左边放个运动图标,右边横着排跑步/骑行/游泳三组,每组上面\"本周已攒 N 张\",提醒我赶紧凑满本月运动合集(还差 7 张),点能跳运动健康 app,有点紧迫感的渐变。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "card": {
      "title": {
        "type": "string",
        "description": "卡片主标题，说明本周运动精彩瞬间的照片收集状态。",
        "sampleValue": "本周已攒"
      }
    },
    "metrics": {
      "run": {
        "label": {
          "type": "string",
          "description": "跑步运动分组标签。",
          "sampleValue": "跑步"
        },
        "countText": {
          "type": "string",
          "description": "跑步分组本周已攒照片数量展示文本。",
          "sampleValue": "12张"
        }
      },
      "cycle": {
        "label": {
          "type": "string",
          "description": "骑行运动分组标签。",
          "sampleValue": "骑行"
        },
        "countText": {
          "type": "string",
          "description": "骑行分组本周已攒照片数量展示文本。",
          "sampleValue": "8张"
        }
      },
      "swim": {
        "label": {
          "type": "string",
          "description": "游泳运动分组标签。",
          "sampleValue": "游泳"
        },
        "countText": {
          "type": "string",
          "description": "游泳分组本周已攒照片数量展示文本。",
          "sampleValue": "5张"
        }
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "跳转运动健康应用的紧迫提醒按钮文案，提示还差的运动合集照片数量。",
        "sampleValue": "凑满本月差7张"
      }
    },
    "asset": {
      "primaryIcon": {
        "type": "string",
        "description": "运动识别主图标资源路径。",
        "sampleValue": "resources/base/media/icon_run.png"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_run.png",
      "description": "运动/跑步图标，适合在相册运动精彩瞬间卡片中作为左侧主视觉识别素材。",
      "bindTo": "/asset/primaryIcon"
    }
  ]
}

